  const req = MODE_UNLOCK[mode];
  if (!req) return true;
  const s = checkUnlocks(playerData);
  return s.total >= (req.pokemon || 0) && s.stage2 >= (req.stage2 || 0)
    && s.stage1 >= (req.stage1 || 0) && s.shinyPct >= (req.shinyPct || 0);
}

